from taf.ul.ettf.events.event import Teardown
from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.scheduler.base_listeners import SuiteListener
from taf.ul.ettf.utils.robot_handlers import TeardownKeywordDecorator
from taf.ul.ettf.utils.robotframework import RobotApi
from taf.ul.ettf.logger import custom_logger
from robot.libraries.BuiltIn import BuiltIn
from collections import namedtuple
import traceback


logger = custom_logger('AutoTeardown')
Data = namedtuple('Data', ['teardown', 'result'])


class AutoTeardown(SuiteListener):

    def __init__(self):
        super(AutoTeardown, self).__init__()
        self.suite_data = None
        self.test_data = None

    def start_suite(self, suite, result):
        teardown = RobotApi().retrieve_teardown(suite)
        RobotApi().replace_teardown(suite, 'auto_suite_teardown')
        self.suite_data = Data(teardown, result)

    def start_test(self, test, result):
        teardown = RobotApi().retrieve_teardown(test)
        RobotApi().replace_teardown(test, 'auto_test_teardown')
        self.test_data = Data(teardown, result)

    @staticmethod
    def _finalize_context(result):
        try:
            Notifier().notify(Teardown(result.passed), TeardownKeywordDecorator(result))
        except Exception as e:
            logger.warn('Finalizing context failed with cause: {}. Traceback: {}'.format(e, traceback.format_exc()))

    def auto_test_teardown(self):
        try:
            self._run_teardown(self.test_data.teardown)
        finally:
            self._finalize_context(self.test_data.result)

    def auto_suite_teardown(self):
        try:
            self._run_teardown(self.suite_data.teardown)
        finally:
            self._finalize_context(self.suite_data.result)

    def _run_teardown(self, teardown):
        if not teardown:
            return
        if teardown.args:
            BuiltIn().run_keyword('{}'.format(teardown.name), *teardown.args)
        else:
            BuiltIn().run_keyword('{}'.format(teardown.name))


auto_teardown = AutoTeardown
